css:
body{margin:0;background:#fff;font-family:system-ui,sans-serif}
  .pcg{--pcg-ink:#344E41;--pcg-mid:#588157;--pcg-soft:#DAD7CD;--pcg-tint:#A3B18A;max-width:880px;margin:0 auto;padding:24px 16px 64px;color:#1f2a22;line-height:1.65}
  .pcg h1{font-size:clamp(1.7rem,4vw,2.4rem);line-height:1.2;color:var(--pcg-ink);margin:8px 0}
  .pcg h2{font-size:1.45rem;color:var(--pcg-ink);margin:40px 0 12px}
  .pcg h3{font-size:1.1rem;margin:20px 0 6px}
  .pcg-crumbs{font-size:.85rem;color:#666}.pcg-crumbs a{color:inherit}
  .pcg-head{display:grid;gap:24px;grid-template-columns:1fr}
  @media(min-width:750px){.pcg-head{grid-template-columns:1.4fr 1fr;align-items:start}}
  .pcg-head__img img{width:100%;height:auto;border-radius:12px}
  .pcg-answer{font-size:1.1rem;background:#f3f5ef;border-left:4px solid var(--pcg-mid);padding:14px 16px;border-radius:6px}
  .pcg-botanical{font-style:italic;color:#555;margin:0 0 6px}
  .pcg-byline{font-size:.82rem;color:#666}
  .pcg-buy{display:flex;flex-wrap:wrap;gap:12px;align-items:center;margin-top:14px;font-weight:600;color:var(--pcg-ink)}
  .pcg-btn{background:var(--pcg-ink);color:#fff !important;text-decoration:none;padding:8px 16px;border-radius:999px;font-weight:600}
  .pcg-facts table,.pcg-table table{width:100%;border-collapse:collapse}
  .pcg-facts th,.pcg-facts td,.pcg-table th,.pcg-table td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--pcg-soft);vertical-align:top}
  .pcg-facts th{width:38%;color:var(--pcg-ink);font-weight:600}
  .pcg-table{overflow-x:auto}.pcg-table thead th{background:#f3f5ef;color:var(--pcg-ink);font-size:.9rem}
  .pcg-table tbody th{font-weight:600;color:var(--pcg-ink)}
  .pcg-fit{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(240px,1fr))}
  .pcg-fit>div{border:1px solid var(--pcg-soft);border-radius:8px;padding:4px 16px}
  .pcg-fit__yes{border-top:4px solid var(--pcg-mid) !important}.pcg-fit__no{border-top:4px solid #b5651d !important}
  .pcg-toc{margin-top:28px;background:#f7f7f4;border-radius:8px;padding:4px 16px 12px}
  .pcg-toc h2{font-size:1rem;margin:12px 0 4px}.pcg-toc ul{margin:0;padding-left:18px}
  .pcg-tips{background:#f3f5ef;border-radius:6px;padding:12px 12px 12px 32px}
  .pcg-steps li{margin-bottom:6px}
  .pcg-shop{font-size:.95rem}.pcg a{color:var(--pcg-mid)}
  .pcg-year{display:grid;gap:12px;grid-template-columns:repeat(auto-fit,minmax(190px,1fr))}
  .pcg-year__card{border:1px solid var(--pcg-soft);border-radius:8px;padding:12px 14px}
  .pcg-year__card h3{margin:0 0 4px}.pcg-year__card span{font-weight:400;font-size:.85rem;color:#666}
  .pcg-year__card p{margin:0;font-size:.95rem}
  .pcg-problem{border-top:1px solid var(--pcg-soft);padding-top:4px;scroll-margin-top:16px}
  .pcg-pets{font-weight:600}.pcg-pets--toxic{color:#8a3b12}
  .pcg-alert{background:#fbefe6;border-left:4px solid #b5651d;padding:12px 14px;border-radius:6px}
  .pcg-faq{border-bottom:1px solid var(--pcg-soft);padding:12px 0}
  .pcg-faq summary{cursor:pointer;font-weight:600;color:var(--pcg-ink)}
  .pcg-faq-group{margin-top:28px}
  .pcg-help{background:#f3f5ef;border-radius:10px;padding:4px 20px 12px}
  .pcg-products{display:grid;gap:14px;grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}
  .pcg-card{display:flex;flex-direction:column;text-decoration:none;color:inherit;font-size:.9rem}
  .pcg-card img{width:100%;height:auto;aspect-ratio:1;object-fit:cover;border-radius:8px}
  .pcg-card__t{margin-top:6px}.pcg-card__p{font-weight:600;color:var(--pcg-ink)}
  .pcg-sources{font-size:.9rem}.pcg-sources li{margin-bottom:4px}

